Command(connection,tx,"""
            SET XACT_ABORT ON;
            DECLARE @result int;
            EXEC @result=sys.sp_getapplock @Resource=N'test-project1:student-write',@LockMode='Exclusive',
                 @LockOwner='Transaction',@LockTimeout=5000,@DbPrincipal='public';
            IF @result<0 THROW 51001,N'保存用ロックを取得できませんでした。',1;
            """)

app.Use(async (ctx,next)=> { ctx.Response.Headers.CacheControl="no-store";ctx.Response.Headers["X-Content-Type-Options"]="nosniff";ctx.Response.Headers["Referrer-Policy"]="no-referrer";ctx.Response.Headers["Content-Security-Policy"]="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'";
            try { await next(); } catch(Exception e) when(!ctx.Response.HasStarted) { var fault=e as WebFault;ctx.Response.StatusCode=fault?.Status??503; if(ctx.Request.Path.StartsWithSegments("/api")) await ctx.Response.WriteAsJsonAsync(WebPresentation.Error(ctx.Response.StatusCode==401?"unauthenticated":ctx.Response.StatusCode==403?"forbidden":ctx.Response.StatusCode==409?"conflict":ctx.Response.StatusCode==422?"validationFailed":"systemError",fault?.Message??"処理結果を確認できません。保存の場合は検索で確認してください。",fault?.MessageId??"E-COM-004",fault?.Field is string field?[new FieldError(field,fault.MessageId,fault.Message)]:[],retry:fault is null)); else { ctx.Response.ContentType="text/html; charset=utf-8";await ctx.Response.WriteAsync("<!doctype html><html lang=ja><meta charset=utf-8><title>学生管理 エラー</title><p>"+System.Net.WebUtility.HtmlEncode(fault?.Message??"処理結果を確認できません。検索で確認してください。")+"</p><a href=/students>検索画面を開く</a></html>"); } }
        })

set.Classes.Where(c=>(year is null||c.SchoolYear==year)&&(string.IsNullOrEmpty(grade)||c.GradeCode==grade)).Select(c=> {
            bool terminal=status is "03" or "04"; bool overlap=DateOnly.TryParse(admission,out var a)&&DateOnly.TryParse(end,out var e)&&c.ValidFrom<=e&&a<=c.ValidTo;
            bool active=c.IsActive&&c.ValidFrom<=today&&today<=c.ValidTo; bool same=draft?.ClassId==c.ClassId;
            return new { classId=c.ClassId.ToString(System.Globalization.CultureInfo.InvariantCulture),c.SchoolYear,c.GradeCode,gradeName=set.Codes.FirstOrDefault(x=>x.CategoryId=="GRADE"&&x.CodeValue==c.GradeCode)?.CodeName??"不整合",c.ClassCode,c.ClassName,selectable=search||same||(terminal?overlap:active),note=!c.IsActive?"停止":today<c.ValidFrom||today>c.ValidTo?"期間外":"",occupancy=(int?)c.Occupied,c.Capacity };
        })

contexts.Use(request,identity.CurrentUser,tab,async entry=> {
            SearchCriteria criteria;
            try { criteria=request.Criteria.ToCriteria(request.PageSize,request.SortKey,request.SortDirection); }
            catch(InputValidationException e) { var error=e.Errors[0]; throw new WebFault(422,error.Message,SearchField(error.Field),error.Code); }
            catch(ArgumentException e) { throw new WebFault(422,e.Message); }
            var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); entry.Draft=SearchContextStore.Copy(request.Criteria);entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result; entry.Revision++; return Present(entry,result); },ct)
